--ACTUALIZACION DE ESTA CUENTA A TIPO CUENTA MARGEN

UPDATE COM_CARREFOUR_JOURNAL_CUENTA C
SET TIPO_ID = (
    SELECT T.ID
    FROM COM_CARREFOUR_JOURNAL_TIPOCUENTA T
    WHERE T.CODIGO = 'MAR'
)
WHERE C.NUMERO IN ('50000000')


