--VER CANTIDAD DE CUENTAS POR TIPOS DE CUENTAS

SELECT T.NOMBRE,count(1)
FROM COM_CARREFOUR_JOURNAL_CUENTA C
INNER JOIN COM_CARREFOUR_JOURNAL_TIPOCUENTA T
ON C.TIPO_ID = T.ID
GROUP BY T.NOMBRE;
